export const KIND = {"id":25,"example":{"id":"E25","kind":25,"source":"aether","statement":["Write a class `scores::board` that keeps a list of scores, with these member functions.","`add(int score)` puts the score at the end of the list.","`all() const` returns the list as a `std::vector<int>`, in the order added.","`last() const` returns the last score added, or 0 when there is none.","A new board holds no scores.","Limits: 0 ≤ each score ≤ 1000; 0 ≤ scores added ≤ 100."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <vector>","","namespace scores {","","class board {","    std::vector<int> scores_ {};","public:","    void add(int score)","    {","        scores_.push_back(score);","    }","    std::vector<int> all() const","    {","        return scores_;","    }","    int last() const","    {","        if (scores_.empty()) {","            return 0;","        }","        return scores_.back();","    }","};","","}  // namespace scores"],"frame":[0,2,4,24,26],"labels":[{"at":6,"level":1,"text":"Write a class that keeps its data in private members."},{"at":9,"level":1,"text":"Write a member function that adds an item to the data."},{"at":9,"level":0,"text":"Write `void` as the type of a function that gives back nothing."},{"at":13,"level":1,"text":"Write a member function that gives back the data."},{"at":17,"level":1,"text":"Write a member function that gives back part of the data."},{"at":19,"level":2,"text":"Give back 0 when the list is empty."},{"at":19,"level":0,"text":"Test whether a list is empty with `empty()`, and get its last item with `back()`."},{"at":22,"level":2,"text":"Give back the last item of the list."}],"blanks":[]}},"trace":{"id":"T25","lines":["#include <iostream>","#include <print>","struct timer","{","    int seconds {0};","};","void add(timer& run, int amount)","{","    run.seconds += amount;","}","int main()","{","    timer run {};","    for (int amount {0}; std::cin >> amount;) {","        add(run, amount);","    }","    std::println(\"{} {}\", run.seconds / 60, run.seconds % 60);","}"],"columns":["amount","run"],"inputs":["50 40\n","100 30 45\n"],"rows":[{"line":13,"values":["","{seconds = 0}"]},{"line":14,"values":["50","{seconds = 0}"]},{"line":9,"values":["50","{seconds = 50}"]},{"line":15,"values":["50","{seconds = 50}"]},{"line":14,"values":["40","{seconds = 50}"]},{"line":9,"values":["40","{seconds = 90}"]},{"line":15,"values":["40","{seconds = 90}"]},{"line":14,"values":["","{seconds = 90}"]},{"line":17,"values":["","{seconds = 90}"]}],"output":"2 55\n"},"traces":[],"problems":{"25.01":{"id":"25.01","kind":25,"source":"exercism","statement":["Write a class `grade_school::school` that keeps names by grade, with these member functions.","`add(const std::string& name, int grade)` puts the name in the grade, unless some grade already has that name.","`roster() const` returns a `std::map<int, std::vector<std::string>>` from each grade that has names to its names in alphabetical order.","`grade(int grade) const` returns a `std::vector<std::string>` of the names in that grade in alphabetical order, or no names when it has none.","A new school has no names.","Limits: 1 ≤ grade ≤ 12; 0 ≤ names added ≤ 100; each name is 1 to 20 letters."],"examples":[{"input":"roster_is_empty_when_no_student_is_added","output":""}],"tests":[{"input":"student_is_added_to_the_roster","output":""},{"input":"multiple_students_in_the_same_grade_are_added_to_the_roster","output":""},{"input":"student_not_added_to_same_grade_in_the_roster_more_than_once","output":""},{"input":"students_in_multiple_grades_are_added_to_the_roster","output":""},{"input":"student_not_added_to_multiple_grades_in_the_roster","output":""},{"input":"students_are_sorted_by_grades_in_the_roster","output":""},{"input":"students_are_sorted_by_name_in_the_roster","output":""},{"input":"students_are_sorted_by_grades_and_then_by_name_in_the_roster","output":""},{"input":"grade_is_empty_if_no_students_in_the_roster","output":""},{"input":"grade_is_empty_if_no_students_in_that_grade","output":""},{"input":"student_not_added_to_same_grade_more_than_once","output":""},{"input":"student_not_added_to_multiple_grades","output":""},{"input":"student_not_added_to_other_grade_for_multiple_grades","output":""},{"input":"students_are_sorted_by_name_in_a_grade","output":""}],"solution":{"lines":["#pragma once","","#include <algorithm>","#include <map>","#include <string>","#include <vector>","","namespace grade_school {","","class school {","    std::map<int, std::vector<std::string>> grades {};","public:","    void add(const std::string& name, int grade)","    {","        for (const auto& [number, names] : grades) {","            if (std::ranges::contains(names, name)) {","                return;","            }","        }","        auto& names {grades[grade]};","        names.push_back(name);","        std::ranges::sort(names);","    }","    std::map<int, std::vector<std::string>> roster() const","    {","        return grades;","    }","    std::vector<std::string> grade(int number) const","    {","        if (!grades.contains(number)) {","            return {};","        }","        return grades.at(number);","    }","};","","}  // namespace grade_school"],"frame":[0,2,3,4,5,7,34,36],"labels":[{"at":9,"level":1,"text":"Write a class that keeps its data in private members."},{"at":12,"level":1,"text":"Write a member function that adds an item to the data."},{"at":14,"level":2,"text":"Give back at once when some grade has the name."},{"at":19,"level":2,"text":"Put the name in its grade, and sort the grade's names."},{"at":23,"level":1,"text":"Write a member function that gives back the data."},{"at":27,"level":1,"text":"Write a member function that gives back part of the data."},{"at":29,"level":2,"text":"Give back no names when the map has no such grade."},{"at":32,"level":2,"text":"Give back the names of the grade."}],"blanks":[{"line":10,"from":4,"to":43},{"line":12,"from":13,"to":47},{"line":15,"from":16,"to":50},{"line":21,"from":26,"to":31},{"line":25,"from":15,"to":21},{"line":27,"from":35,"to":45},{"line":29,"from":12,"to":36},{"line":32,"from":15,"to":32}]},"fn":{"slug":"grade-school","commit":"8d139cb0","header":"grade_school.h","name":"grade_school_test.cpp","test":"#include \"grade_school.h\"\n\n#include <map>\n#include <string>\n#include <vector>\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\nusing namespace std;\n\nTEST_CASE(\"roster_is_empty_when_no_student_is_added\",\n          \"[a3f0fb58-f240-4723-8ddc-e644666b85cc]\") {\n    const grade_school::school school{};\n\n    REQUIRE(school.roster().empty());\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"student_is_added_to_the_roster\",\n          \"[6d0a30e4-1b4e-472e-8e20-c41702125667]\") {\n    grade_school::school school;\n    school.add(\"Aimee\", 2);\n\n    const map<int, vector<string>> expected{{2, {\"Aimee\"}}};\n    REQUIRE(expected == school.roster());\n}\n\nTEST_CASE(\"multiple_students_in_the_same_grade_are_added_to_the_roster\",\n          \"[233be705-dd58-4968-889d-fb3c7954c9cc]\") {\n    grade_school::school school;\n    school.add(\"Blair\", 2);\n    school.add(\"James\", 2);\n    school.add(\"Paul\", 2);\n\n    const map<int, vector<string>> expected{{2, {\"Blair\", \"James\", \"Paul\"}}};\n    REQUIRE(expected == school.roster());\n}\n\nTEST_CASE(\"student_not_added_to_same_grade_in_the_roster_more_than_once\",\n          \"[d7982c4f-1602-49f6-a651-620f2614243a]\") {\n    grade_school::school school;\n    school.add(\"Blair\", 2);\n    school.add(\"James\", 2);\n    school.add(\"James\", 2);\n    school.add(\"Paul\", 2);\n\n    const map<int, vector<string>> expected{{2, {\"Blair\", \"James\", \"Paul\"}}};\n    REQUIRE(expected == school.roster());\n}\n\nTEST_CASE(\"students_in_multiple_grades_are_added_to_the_roster\",\n          \"[75a51579-d1d7-407c-a2f8-2166e984e8ab]\") {\n    grade_school::school school;\n    school.add(\"Chelsea\", 3);\n    school.add(\"Logan\", 7);\n\n    const map<int, vector<string>> expected{{3, {\"Chelsea\"}}, {7, {\"Logan\"}}};\n    REQUIRE(expected == school.roster());\n}\n\nTEST_CASE(\"student_not_added_to_multiple_grades_in_the_roster\",\n          \"[c7ec1c5e-9ab7-4d3b-be5c-29f2f7a237c5]\") {\n    grade_school::school school;\n    school.add(\"Blair\", 2);\n    school.add(\"James\", 2);\n    school.add(\"James\", 3);\n    school.add(\"Paul\", 3);\n\n    const map<int, vector<string>> expected{{2, {\"Blair\", \"James\"}},\n                                            {3, {\"Paul\"}}};\n    REQUIRE(expected == school.roster());\n}\n\nTEST_CASE(\"students_are_sorted_by_grades_in_the_roster\",\n          \"[d9af4f19-1ba1-48e7-94d0-dabda4e5aba6]\") {\n    grade_school::school school;\n    school.add(\"Jim\", 3);\n    school.add(\"Peter\", 2);\n    school.add(\"Anna\", 1);\n\n    const map<int, vector<string>> expected{\n        {1, {\"Anna\"}}, {2, {\"Peter\"}}, {3, {\"Jim\"}}};\n    REQUIRE(expected == school.roster());\n}\n\nTEST_CASE(\"students_are_sorted_by_name_in_the_roster\",\n          \"[d9fb5bea-f5aa-4524-9d61-c158d8906807]\") {\n    grade_school::school school;\n    school.add(\"Peter\", 2);\n    school.add(\"Zoe\", 2);\n    school.add(\"Alex\", 2);\n\n    const map<int, vector<string>> expected{{2, {\"Alex\", \"Peter\", \"Zoe\"}}};\n    REQUIRE(expected == school.roster());\n}\n\nTEST_CASE(\"students_are_sorted_by_grades_and_then_by_name_in_the_roster\",\n          \"[180a8ff9-5b94-43fc-9db1-d46b4a8c93b6]\") {\n    grade_school::school school;\n    school.add(\"Peter\", 2);\n    school.add(\"Anna\", 1);\n    school.add(\"Barb\", 1);\n    school.add(\"Zoe\", 2);\n    school.add(\"Alex\", 2);\n    school.add(\"Jim\", 3);\n    school.add(\"Charlie\", 1);\n\n    const map<int, vector<string>> expected{{1, {\"Anna\", \"Barb\", \"Charlie\"}},\n                                            {2, {\"Alex\", \"Peter\", \"Zoe\"}},\n                                            {3, {\"Jim\"}}};\n    REQUIRE(expected == school.roster());\n}\n\nTEST_CASE(\"grade_is_empty_if_no_students_in_the_roster\",\n          \"[5e67aa3c-a3c6-4407-a183-d8fe59cd1630]\") {\n    const grade_school::school school{};\n\n    REQUIRE(school.grade(1).empty());\n}\n\nTEST_CASE(\"grade_is_empty_if_no_students_in_that_grade\",\n          \"[1e0cf06b-26e0-4526-af2d-a2e2df6a51d6]\") {\n    grade_school::school school;\n    school.add(\"Peter\", 2);\n    school.add(\"Zoe\", 2);\n    school.add(\"Alex\", 2);\n    school.add(\"Jim\", 3);\n\n    const vector<string> expected{};\n    REQUIRE(expected == school.grade(1));\n}\n\nTEST_CASE(\"student_not_added_to_same_grade_more_than_once\",\n          \"[2bfc697c-adf2-4b65-8d0f-c46e085f796e]\") {\n    grade_school::school school;\n    school.add(\"Blair\", 2);\n    school.add(\"James\", 2);\n    school.add(\"James\", 2);\n    school.add(\"Paul\", 2);\n\n    const vector<string> expected{\"Blair\", \"James\", \"Paul\"};\n    REQUIRE(expected == school.grade(2));\n}\n\nTEST_CASE(\"student_not_added_to_multiple_grades\",\n          \"[66c8e141-68ab-4a04-a15a-c28bc07fe6b9]\") {\n    grade_school::school school;\n    school.add(\"Blair\", 2);\n    school.add(\"James\", 2);\n    school.add(\"James\", 3);\n    school.add(\"Paul\", 3);\n\n    const vector<string> expected{\"Blair\", \"James\"};\n    REQUIRE(expected == school.grade(2));\n}\n\nTEST_CASE(\"student_not_added_to_other_grade_for_multiple_grades\",\n          \"[c9c1fc2f-42e0-4d2c-b361-99271f03eda7]\") {\n    grade_school::school school;\n    school.add(\"Blair\", 2);\n    school.add(\"James\", 2);\n    school.add(\"James\", 3);\n    school.add(\"Paul\", 3);\n\n    const vector<string> expected{\"Paul\"};\n    REQUIRE(expected == school.grade(3));\n}\n\nTEST_CASE(\"students_are_sorted_by_name_in_a_grade\",\n          \"[1bfbcef1-e4a3-49e8-8d22-f6f9f386187e]\") {\n    grade_school::school school;\n    school.add(\"Franklin\", 5);\n    school.add(\"Bradley\", 5);\n    school.add(\"Jeff\", 1);\n\n    const vector<string> expected{\"Bradley\", \"Franklin\"};\n    REQUIRE(expected == school.grade(5));\n}\n\n#endif\n","setup":["const grade_school::school school{};"],"calls":[{"call":"school.roster().empty()","expected":"true"}]}},"25.02":{"id":"25.02","kind":25,"source":"aether","statement":["Write a class `inventory::store` that keeps an amount for each item, with these member functions.","`add(const std::string& item, int number)` adds number to the amount of the item.","`stock() const` returns a `std::map<std::string, int>` from each item added to its amount.","`amount(const std::string& item) const` returns the amount of the item, or 0 for an item never added.","A new store holds no items.","Limits: 1 ≤ number ≤ 1000; 0 ≤ items added ≤ 100; each item is 1 to 20 small letters."],"examples":[{"input":"amounts_add_up","output":""}],"tests":[{"input":"new_store_has_no_items","output":""},{"input":"item_never_added_has_amount_0","output":""},{"input":"one_item_added_once","output":""},{"input":"stock_holds_every_item","output":""},{"input":"largest_amounts","output":""},{"input":"many_items","output":""}],"solution":{"lines":["#pragma once","","#include <map>","#include <string>","","namespace inventory {","","class store {","    std::map<std::string, int> amounts_ {};","public:","    void add(const std::string& item, int number)","    {","        amounts_[item] += number;","    }","    std::map<std::string, int> stock() const","    {","        return amounts_;","    }","    int amount(const std::string& item) const","    {","        if (!amounts_.contains(item)) {","            return 0;","        }","        return amounts_.at(item);","    }","};","","}  // namespace inventory"],"frame":[0,2,3,5,25,27],"labels":[{"at":7,"level":1,"text":"Write a class that keeps its data in private members."},{"at":10,"level":1,"text":"Write a member function that adds an item to the data."},{"at":14,"level":1,"text":"Write a member function that gives back the data."},{"at":18,"level":1,"text":"Write a member function that gives back part of the data."},{"at":20,"level":2,"text":"Give back 0 when the map has no such item."},{"at":23,"level":2,"text":"Give back the amount of the item."}],"blanks":[{"line":8,"from":4,"to":30},{"line":12,"from":26,"to":32},{"line":16,"from":15,"to":23},{"line":18,"from":15,"to":38},{"line":20,"from":12,"to":36},{"line":23,"from":15,"to":32}]},"fn":{"slug":"inventory","commit":"","header":"inventory.h","name":"inventory_test.cpp","test":"#include \"inventory.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"amounts_add_up\")\n{\n    inventory::store shop {};\n    shop.add(\"apple\", 3);\n    shop.add(\"pear\", 2);\n    shop.add(\"apple\", 4);\n    REQUIRE(shop.amount(\"apple\") == 7);\n}\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"new_store_has_no_items\")\n{\n    const inventory::store shop {};\n    REQUIRE(shop.stock().empty());\n}\nTEST_CASE(\"item_never_added_has_amount_0\")\n{\n    inventory::store shop {};\n    shop.add(\"pear\", 5);\n    REQUIRE(shop.amount(\"plum\") == 0);\n}\nTEST_CASE(\"one_item_added_once\")\n{\n    inventory::store shop {};\n    shop.add(\"fig\", 1);\n    REQUIRE(shop.amount(\"fig\") == 1);\n    const std::map<std::string, int> expected {{\"fig\", 1}};\n    REQUIRE(shop.stock() == expected);\n}\nTEST_CASE(\"stock_holds_every_item\")\n{\n    inventory::store shop {};\n    shop.add(\"pear\", 2);\n    shop.add(\"apple\", 3);\n    shop.add(\"pear\", 10);\n    const std::map<std::string, int> expected {\n        {\"apple\", 3}, {\"pear\", 12}};\n    REQUIRE(shop.stock() == expected);\n}\nTEST_CASE(\"largest_amounts\")\n{\n    inventory::store shop {};\n    for (int index {0}; index < 100; ++index) {\n        shop.add(\"plum\", 1000);\n    }\n    REQUIRE(shop.amount(\"plum\") == 100000);\n}\nTEST_CASE(\"many_items\")\n{\n    inventory::store shop {};\n    for (int index {0}; index < 100; ++index) {\n        shop.add(std::string(1 + index % 20, 'a'), index + 1);\n    }\n    REQUIRE(shop.stock().size() == 20);\n    REQUIRE(shop.amount(\"a\") == 1 + 21 + 41 + 61 + 81);\n}\n#endif\n","setup":["inventory::store shop {};","shop.add(\"apple\", 3);","shop.add(\"pear\", 2);","shop.add(\"apple\", 4);"],"calls":[{"call":"shop.amount(\"apple\")","expected":"7"}]}}}}
